class Solution {
public:
    string validIPAddress(string queryIP) {
        if (count(queryIP.begin(), queryIP.end(), '.') == 3) {
            stringstream ss(queryIP);
            string part;
            int countParts = 0;
            while (getline(ss, part, '.')) {
                countParts++;
                if (part.empty() || part.size() > 3) return "Neither";
                if (part.size() > 1 && part[0] == '0') return "Neither";
                for (char c : part) if (!isdigit(c)) return "Neither";
                int val = stoi(part);
                if (val < 0 || val > 255) return "Neither";
            }
            if (queryIP.back() == '.') return "Neither";
            return countParts == 4 ? "IPv4" : "Neither";
        } else if (count(queryIP.begin(), queryIP.end(), ':') == 7) {
            stringstream ss(queryIP);
            string part;
            int countParts = 0;
            while (getline(ss, part, ':')) {
                countParts++;
                if (part.empty() || part.size() > 4) return "Neither";
                for (char c : part) {
                    if (!isxdigit(c)) return "Neither";
                }
            }
            if (queryIP.back() == ':') return "Neither";
            return countParts == 8 ? "IPv6" : "Neither";
        }
        return "Neither";
    }
};

class Solution {
    public String validIPAddress(String queryIP) {
        if (queryIP.chars().filter(c -> c == '.').count() == 3) {
            String[] parts = queryIP.split("\\.", -1);
            if (parts.length != 4) return "Neither";
            for (String p : parts) {
                if (p.length() == 0 || p.length() > 3) return "Neither";
                if (p.length() > 1 && p.charAt(0) == '0') return "Neither";
                for (char c : p.toCharArray()) if (!Character.isDigit(c)) return "Neither";
                int val = Integer.parseInt(p);
                if (val < 0 || val > 255) return "Neither";
            }
            return "IPv4";
        } else if (queryIP.chars().filter(c -> c == ':').count() == 7) {
            String[] parts = queryIP.split(":", -1);
            if (parts.length != 8) return "Neither";
            String hex = "0123456789abcdefABCDEF";
            for (String p : parts) {
                if (p.length() == 0 || p.length() > 4) return "Neither";
                for (char c : p.toCharArray()) if (hex.indexOf(c) == -1) return "Neither";
            }
            return "IPv6";
        }
        return "Neither";
    }
}

/**
 * @param {string} queryIP
 * @return {string}
 */
var validIPAddress = function(queryIP) {
    const dotCount = (queryIP.match(/\./g) || []).length;
    const colonCount = (queryIP.match(/:/g) || []).length;
    if (dotCount === 3) {
        const parts = queryIP.split('.');
        if (parts.length !== 4) return "Neither";
        for (const p of parts) {
            if (!p || p.length > 3) return "Neither";
            if (p.length > 1 && p[0] === '0') return "Neither";
            if (!/^[0-9]+$/.test(p)) return "Neither";
            const val = parseInt(p, 10);
            if (val < 0 || val > 255) return "Neither";
        }
        return "IPv4";
    } else if (colonCount === 7) {
        const parts = queryIP.split(':');
        if (parts.length !== 8) return "Neither";
        for (const p of parts) {
            if (!p || p.length > 4) return "Neither";
            if (!/^[0-9a-fA-F]+$/.test(p)) return "Neither";
        }
        return "IPv6";
    }
    return "Neither";
};
